import { readFileSync } from "node:fs";
import { join } from "node:path";
import { getAgentDir } from "../../config.ts";
import { getFeatureOption, loadInstallFeatures } from "../install-features.ts";

const listeners = new Set<(enabled: boolean) => void>();

export function browserEnabledDefault(): boolean {
	return loadInstallFeatures().features.browser?.enabled !== false;
}

export function readBrowserSettings(): { enabled: boolean; allowPrivate: boolean } {
	let settings: Record<string, unknown> = {};
	try { settings = JSON.parse(readFileSync(join(getAgentDir(), "settings.json"), "utf8")) ?? {}; } catch {}
	return {
		enabled: typeof settings.browserEnabled === "boolean" ? settings.browserEnabled : browserEnabledDefault(),
		allowPrivate: typeof settings.browserAllowPrivateNetwork === "boolean" ? settings.browserAllowPrivateNetwork : getFeatureOption("browser", "allow-private-network") === true,
	};
}

export function onBrowserEnabledChange(listener: (enabled: boolean) => void): () => void {
	listeners.add(listener);
	return () => listeners.delete(listener);
}

export function notifyBrowserEnabledChange(enabled: boolean): void {
	for (const listener of listeners) listener(enabled);
}

import { spawnSync } from "node:child_process";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";

const truthy = (value) => /^(1|true|yes)$/i.test(value ?? "");
const explicit = process.argv.includes("--explicit");
if ([process.env.PI_OFFLINE, process.env.npm_config_offline, process.env.PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD, process.env.npm_config_package_lock_only].some(truthy)) {
	console.error("Chromium installation skipped for offline/skip-download mode. If needed later, run: lunr browser install");
} else {
	try {
		const require = createRequire(import.meta.url);
		const cli = join(dirname(require.resolve("playwright-core/package.json")), "cli.js");
		const result = spawnSync(process.execPath, [cli, "install", "chromium"], { stdio: "inherit", windowsHide: true });
		if (result.error) throw result.error;
		if (result.status !== 0) throw new Error(`Chromium installer exited ${result.status}`);
	} catch (error) {
		console.error(`Chromium is not ready: ${error instanceof Error ? error.message : String(error)}. Other lunr tools remain available. Run lunr browser install when online.`);
		if (explicit) process.exitCode = 1;
	}
}

import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";

export async function installBrowser(): Promise<void> {
	const script = fileURLToPath(new URL("../../../scripts/install-browser.mjs", import.meta.url));
	await new Promise<void>((resolve, reject) => {
		const child = spawn(process.execPath, [script, "--explicit"], { stdio: "inherit", windowsHide: true });
		child.once("error", reject);
		child.once("exit", (code) => {
			if (code === 0) resolve();
			else reject(new Error(`Chromium setup failed (${code}). Retry lunr browser install when online.`));
		});
	});
}

