	const code = await spawn(command, installArgv);
	process.exitCode = code === 0 || code === null ? 0 : code;
	if ((process.exitCode ?? 0) === 0) {
		log(`Updated ${APP_NAME} ${result.current} → ${result.latest}.`);
	}
	return true;
}

